// Verify Supabase 'Send SMS Hook' (Standard Webhooks) and extract phone + otp.
const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};

// raw body (rawBody:true) comes as a string; fall back to parsed body
let raw = item.body;
if (raw && typeof raw === 'object') raw = JSON.stringify(raw);

// ---- signature check (set SUPABASE_SMS_HOOK_VERIFY=false to skip while testing) ----
const doVerify = ($env.SUPABASE_SMS_HOOK_VERIFY || 'true') !== 'false';
if (doVerify) {
  const secretRaw = ($env.SUPABASE_SMS_HOOK_SECRET || '').trim();
  const b64 = secretRaw.replace('v1,whsec_', '').replace('whsec_', '');
  const id = headers['webhook-id'];
  const ts = headers['webhook-timestamp'];
  const sigHeader = headers['webhook-signature'] || '';
  const signed = `${id}.${ts}.${raw}`;
  const key = Buffer.from(b64, 'base64');
  const expected = crypto.createHmac('sha256', key).update(signed).digest('base64');
  const ok = String(sigHeader).split(' ').some(s => s.split(',')[1] === expected);
  if (!ok) throw new Error('Invalid Supabase webhook signature');
}

const body = typeof raw === 'string' ? JSON.parse(raw) : raw;
const phone = String(body.user && body.user.phone || '').replace(/\D/g, '');
const numbers = phone.replace(/^91/, '').slice(-10);
const otp = String(body.sms && body.sms.otp || '');
if (numbers.length !== 10 || !otp) throw new Error('Missing phone or otp in payload');
return [{ json: { numbers, otp } }];
